   "svg": "<svg viewBox=\"0 0 600 300\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect width=\"600\" height=\"300\" fill=\"#f8fafc\"/>\n<text x=\"300\" y=\"30\" font-size=\"18\" fill=\"#0f172a\" text-anchor=\"middle\" font-weight=\"bold\">Su 100 parti di territorio italiano…</text>\n<rect x=\"60\" y=\"90\" width=\"120\" height=\"140\" fill=\"#a16207\"/>\n<rect x=\"240\" y=\"64\" width=\"120\" height=\"166\" fill=\"#84cc16\"/>\n<rect x=\"420\" y=\"137\" width=\"120\" height=\"93\" fill=\"#facc15\"/>\n<text x=\"120\" y=\"80\" font-size=\"22\" fill=\"#713f12\" text-anchor=\"middle\" font-weight=\"bold\">35</text>\n<text x=\"300\" y=\"54\" font-size=\"22\" fill=\"#3f6212\" text-anchor=\"middle\" font-weight=\"bold\">42</text>\n<text x=\"480\" y=\"127\" font-size=\"22\" fill=\"#854d0e\" text-anchor=\"middle\" font-weight=\"bold\">23</text>\n<line x1=\"40\" y1=\"230\" x2=\"560\" y2=\"230\" stroke=\"#0f172a\" stroke-width=\"2\"/>\n<text x=\"120\" y=\"258\" font-size=\"18\" fill=\"#0f172a\" text-anchor=\"middle\">⛰️ montagna</text>\n<text x=\"300\" y=\"258\" font-size=\"18\" fill=\"#0f172a\" text-anchor=\"middle\">🌄 collina</text>\n<text x=\"480\" y=\"258\" font-size=\"18\" fill=\"#0f172a\" text-anchor=\"middle\">🌾 pianura</text>\n<text x=\"300\" y=\"288\" font-size=\"15\" fill=\"#475569\" text-anchor=\"middle\">valori arrotondati (fonte: ISTAT)</text>\n</svg>",
